def t(label,text=None,behavior=None):
 b=I[label];r={'source':b['path'],'label':label,'line':b['line'],'current':b['text'] or '\n'.join(b['code'])}
 if text is not None:r['replacement_text']=text
 if behavior:r['final_behavior']=behavior
 return r
