# Record boards: current read-only API is owned centrally. Local roots are exact and exhaustive.
raw=json.loads((W/'inventory.raw.json').read_text());rr=[]
for m in raw['maps']:
 if not m['name'].startswith('BattleFrontier'):continue
 for e in m['events']:
  lab=e.get('root') or ''
  if lab in I and any(v in lab for v in ['ShowSinglesResults','ShowDoublesResults','ShowMultisResults','ShowLinkMultisResults','ShowPrevTourneyTree','ShowResults','TowerSinglesRecords','TowerDoublesRecords','TowerMultisRecords','TowerLinkRecords','ArenaRecords','PalaceRecords','FactoryRecords','DomeRecords','PikeRecords','PyramidRecords']):
   if any(v['label']==lab for v in rr):continue
   rr.append(t(lab,behavior='Replace body with: special ChampionsCircuitBufferRecord; msgbox BattleFrontier_BattleTowerLobby_Text_CurrentCircuitRecord, MSGBOX_SIGN; end. FAC-03 binds STR_VAR_1 to current VAR_CHAMPIONS_CIRCUIT_CURRENT_WINS, STR_VAR_2 to Best recorded VAR_EC_CIRCUIT_BEST_WINS (display -- when no observed record), STR_VAR_3 to lifetime VAR_CHAMPIONS_CIRCUIT_TOTAL_WINS. Five decimal digits must fit. Viewing never mutates state; retained old facility record data does not become a live challenge.'))
rr.append({'source':'data/maps/BattleFrontier_BattleTowerLobby/scripts.inc','label':'BattleFrontier_BattleTowerLobby_Text_CurrentCircuitRecord','new_label':True,'replacement_text':'CHAMPIONS CIRCUIT\\pCurrent run: {STR_VAR_1}\\pBest recorded: {STR_VAR_2}\\pTotal wins: {STR_VAR_3}'})
rr += [t('BattleFrontier_RankingHall_Text_ExplainRankingHall',"This hall celebrates the\nFrontier's competitive history.\\pToday's boards show CHAMPIONS\nCIRCUIT results: the current run,\nbest recorded run, and total wins."),t('BattleFrontier_RankingHall_Text_DomePikeFactoryRecords',"CHAMPIONS CIRCUIT RECORDS\nCurrent run, best recorded, total wins"),t('BattleFrontier_RankingHall_Text_PalaceArenaPyramidRecords',"CHAMPIONS CIRCUIT RECORDS\nCurrent run, best recorded, total wins")]
add('W-CIRCUIT-RECORDS','Show actual Circuit progress on current record boards','Existing monitors read retired mode counters. A current standard competition needs records tied to the same state that governs its results and entitlements, without a second scoreboard state.',rr,['FAC-03: CURRENT_WINS0x40DB, TOTAL_WINS0x40DC, proposed BEST_WINS0x40E3; initialize best only from observed currentrun, never infer historical best from lifetime. Legacy record data preserved'],['After Circuit wins, withdrawal, loss and reload, each current board matches the same authoritative counters. Tent/Hill wins do not change these values. Viewing any record cannot claim rewards, alter streaks or start a battle.'])
# Geometry evidence for the opening actors.
paths={}
for lab,start in [('Route101_Movement_BirchRunAway1',(0,15)),('Route101_Movement_ZigzagoonChase1',(0,16)),('Route101_Movement_BirchRunInCircles',(4,13)),('Route101_Movement_ZigzagoonChaseInCircles',(4,14))]:
 x,y=start;cells=[(x,y)]
 for line in I[lab]['code']:
  match=re.fullmatch(r'walk_fast_(up|down|left|right)',line)
  if match:
   dx,dy={'up':(0,-1),'down':(0,1),'left':(-1,0),'right':(1,0)}[match[1]];x+=dx;y+=dy;cells.append((x,y))
 paths[lab]={'start':start,'end':(x,y),'visited_cells':cells}
(S/'data/maps/Route101/map.json').exists()
(W/'opening-geometry.json').write_text(json.dumps({'scope':'Discrete source movement endpoints, not rendered or runtime collision proof','paths':paths,'new_actor_initial':[6,14],'new_actor_rest':[6,13],'bag':[7,14],'player_trigger_starts':[[10,19],[11,19]],'player_rest':[[10,15],[11,15]],'after_win_player':[6,13]},indent=2)+'\n')
